"""TSVC tsvc_2 s316: result[0] = min(a[:LEN_1D]).

Fast path: persistent pthread pool + AVX-512 4-lane streaming min in a
bundled C extension (loaded from a path in the shared folder, or from an
embedded base64 copy).  Fallback: NumPy pool.  Small inputs: Numba scalar.
Everything is warmed at import time, outside the timed section.
"""
import os
import ctypes
import base64
import tempfile
import numpy as np
from concurrent.futures import ThreadPoolExecutor
from numba import njit

_B64 = ""


def _setup(L):
    L.minred_init.argtypes = [ctypes.c_int]
    L.minred_init.restype = ctypes.c_int
    L.minred.argtypes = [ctypes.c_void_p, ctypes.c_int64]
    L.minred.restype = ctypes.c_double


def _load_lib():
    cands = []
    try:
        cands.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "libminred.so"))
    except Exception:
        pass
    cands.append("/shared/agent-29/libminred.so")
    for p in cands:
        try:
            if os.path.exists(p):
                L = ctypes.CDLL(p)
                _setup(L)
                return L
        except Exception:
            pass
    try:
        fd, tmp = tempfile.mkstemp(suffix=".so")
        os.write(fd, base64.b64decode(_B64))
        os.close(fd)
        L = ctypes.CDLL(tmp)
        _setup(L)
        return L
    except Exception:
        return None


_lib = _load_lib()


@njit(fastmath=True)
def _min1(a, n):
    x = a[0]
    for i in range(1, n):
        if a[i] < x:
            x = a[i]
    return x


_NT = 0
if _lib is not None:
    _aff = len(os.sched_getaffinity(0))
    if _lib.minred_init(min(_aff, 24)) == 0:
        _NT = min(_aff, 24)

if _NT == 0:
    _pool = ThreadPoolExecutor(max_workers=24)
    _parts = np.empty(24, np.float64)

    def _minp(a, n):
        nt = 24
        ch = (n + nt - 1) // nt
        def f(i):
            lo = i * ch
            hi = n if lo + ch > n else lo + ch
            _parts[i] = np.min(a[lo:hi]) if lo < hi else np.inf
        list(_pool.map(f, range(nt)))
        return float(np.min(_parts))

    def _minp2(a, n):
        return _minp(a, n)
else:
    def _minp(a, n):
        return _lib.minred(a.ctypes.data, n)

    _minp2 = _minp

_w = np.arange(1 << 16, dtype=np.float64)
for _ in range(3):
    _min1(_w, _w.shape[0])
    _minp(_w, _w.shape[0])

_SMALL = 1 << 20


def s316(a, result, LEN_1D):
    n = int(LEN_1D)
    if n <= 1:
        result[0] = a[0]
        return None
    if n <= _SMALL:
        x = _min1(a, n)
    else:
        x = _minp(a, n)
    result[0] = x
    return None
